// PATCH /api/v1/devices/{id}  con  Authorization: Basic <token>
// deviceId y state los pone el propio nodo inject (msg.deviceId / msg.state).
// Token fijo (el mismo capturado del tráfico real de la app) - no depende de
// Environment Variables, así no hay que configurar nada aparte en Node-RED.
const BASIC_TOKEN = 'YWRtaW46ODk5YTgwNzI3ZGExZGYwOGIxNTEzNmE4YTg5OTUwNjMzYjFjODQ0NmQyZjYwZWFlZmUyNTExMWRmZjVmNTg5MQ==';

msg.headers = {
    'Authorization': 'Basic ' + BASIC_TOKEN,
    'Content-Type': 'application/json'
};
msg.url = 'http://192.168.1.133:8000/api/v1/devices/' + msg.deviceId;
msg.payload = { socket: { default: { state: msg.state } } };
return msg;

flow.set('pendingAction', msg.payload);
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = {
    grant_type: 'client_credentials',
    client_id: env.get('SCHUKO_CLIENT_ID'),
    client_secret: env.get('SCHUKO_CLIENT_SECRET')
};
return msg;

const action = flow.get('pendingAction');
msg.headers = {
    'Authorization': 'Bearer ' + msg.payload.access_token,
    'Content-Type': 'application/json'
};
msg.payload = { socket: { default: { state: action.state } } };
msg.url = 'http://192.168.1.133:8000/api/v1/devices/' + action.deviceId;
return msg;

// AJUSTA a tu Grafana: URL accesible desde Node-RED, y una API key/service
// account token con permiso de escritura de anotaciones (Administration ->
// Service accounts -> crea uno con rol Editor -> genera token).
const GRAFANA_URL = 'http://localhost:3000';
const GRAFANA_API_KEY = 'glsa_fwLD4Cx1OjbABpDu6BKJzaC7McF2uw9a_4669f828';

const code = msg.statusCode || 0;
const ok = code > 0 && code < 400;
const deviceId = msg.deviceId || 'unknown';
const action = msg.state ? 'on' : 'off'; // msg.state lo puso el inject (Encender=true / Apagar=false)
const combo = action + '_' + (ok ? 'success' : 'fail'); // on_success | on_fail | off_success | off_fail

msg.headers = {
    'Content-Type': 'application/json',
    'Authorization': 'Bearer ' + GRAFANA_API_KEY
};
msg.url = GRAFANA_URL + '/api/annotations';
msg.payload = {
    time: Date.now(),
    tags: ['simonio', 'command', 'deviceId:' + deviceId, 'http', action, ok ? 'success' : 'fail', combo],
    text: 'Comando HTTP PATCH (' + action + ') -> ' + code + (ok ? ' (éxito)' : ' (fallo)')
};
return msg;

// Sin base de datos externa: solo actualiza el contador en memoria de
// Node-RED (contexto global). Lo expone luego el endpoint HTTP
// GET /simonio/stats (nodos 'Endpoint estadísticas' más abajo en esta
// misma pestaña) para que Grafana lo lea con el plugin Infinity.
// AVISO: si reinicias Node-RED sin contexto persistente configurado
// (settings.js -> contextStorage), estos contadores vuelven a 0.
const code = msg.statusCode || 0;
const ok = code > 0 && code < 400;
const deviceId = msg.deviceId || 'unknown';
const action = msg.state ? 'on' : 'off';
const result = ok ? 'success' : 'fail';

const key = 'simonio_count_' + deviceId + '_' + action + '_' + result;
const count = (global.get(key) || 0) + 1;
global.set(key, count);

return msg; // avisa al runner de la cola para que lance el siguiente caso

// Recorre todas las claves 'simonio_count_...' del contexto global y las
// convierte en una lista de objetos, para que Grafana (vía plugin Infinity)
// pueda leerlas como filas de una tabla.
const keys = global.keys().filter(k => k.startsWith('simonio_count_'));

const rows = keys.map(k => {
    // simonio_count_{deviceId}_{action}_{result}
    const rest = k.substring('simonio_count_'.length);
    const parts = rest.split('_');
    const result = parts.pop();       // success | fail
    const action = parts.pop();       // on | off
    const deviceId = parts.join('_'); // por si el deviceId tuviera guiones bajos
    return {
        deviceId: deviceId,
        action: action,
        result: result,
        count: global.get(k) || 0
    };
});

msg.statusCode = 200;
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = rows;
return msg;

// GET /api/v1/devices -> lista de dispositivos de la instalacion.
// Mismo Basic Auth que el resto de llamadas HTTP (token fijo, confirmado
// por trafico real de la app). No depende de Environment Variables.
const BASIC_TOKEN = 'YWRtaW46ODk5YTgwNzI3ZGExZGYwOGIxNTEzNmE4YTg5OTUwNjMzYjFjODQ0NmQyZjYwZWFlZmUyNTExMWRmZjVmNTg5MQ==';

msg.headers = {
    'Authorization': 'Basic ' + BASIC_TOKEN
};
msg.url = 'http://192.168.1.133:8000/api/v1/devices';
return msg;

// Reutiliza el mismo Grafana que el resto de anotaciones: pega aqui la
// misma GRAFANA_API_KEY que ya tienes puesta en el nodo
// 'Preparar anotacion Grafana (exito/fallo)' para no duplicar el secreto
// en dos sitios con valores distintos.
const GRAFANA_URL = 'http://localhost:3000';
const GRAFANA_API_KEY = 'PON_AQUI_TU_GRAFANA_API_KEY';

const code = msg.statusCode || 0;
const ok = code === 200; // aqui el exito se define simplemente como codigo 200
const count = Array.isArray(msg.payload) ? msg.payload.length
    : (msg.payload && typeof msg.payload.count === 'number') ? msg.payload.count
    : null;

msg.headers = {
    'Content-Type': 'application/json',
    'Authorization': 'Bearer ' + GRAFANA_API_KEY
};
msg.url = GRAFANA_URL + '/api/annotations';
msg.payload = {
    time: Date.now(),
    tags: ['simonio', 'command', 'http', 'get_devices', ok ? 'success' : 'fail'],
    text: 'GET /devices -> ' + code + (count !== null ? ' (' + count + ' dispositivos)' : '') + (ok ? ' (exito)' : ' (fallo)')
};
return msg;

// Mismo mecanismo en memoria (sin InfluxDB) que el resto de contadores,
// expuesto tambien por GET /simonio/stats. Aqui el 'ok' es simplemente
// que el codigo de estado HTTP sea 200.
const code = msg.statusCode || 0;
const ok = code === 200;
const result = ok ? 'success' : 'fail';

const key = 'simonio_count_installation_getDevices_' + result;
const count = (global.get(key) || 0) + 1;
global.set(key, count);

return msg; // avisa al runner de la cola para que lance el siguiente caso

// UNICO sitio que se toca para anadir/quitar/reordenar casos de prueba.
// Cada objeto describe un caso; 'tipo' decide como se enruta mas abajo.
flow.set('cola_pruebas', [
    { tipo: 'encender',        deviceId: '3' },
    { tipo: 'apagar',          deviceId: '3' },
    { tipo: 'get_dispositivos' }
    // { tipo: 'encender', deviceId: '7' },  <- ejemplo: mismo caso, otro dispositivo
]);
return msg;

// Nodo generico: saca el siguiente caso de la cola y lo enruta.
// Se llama a si mismo (via el Switch + el final de cada caso) hasta
// vaciar la cola. No requiere ningun inject ni nodo nuevo por caso.
const cola = flow.get('cola_pruebas') || [];

if (cola.length === 0) {
    node.status({ fill: 'green', shape: 'dot', text: 'bateria completada' });
    return null;
}

const caso = cola.shift();
flow.set('cola_pruebas', cola);
node.status({ fill: 'blue', shape: 'dot', text: 'ejecutando: ' + caso.tipo + ' (' + cola.length + ' restantes)' });

msg.tipo = caso.tipo;
msg.deviceId = caso.deviceId;
msg.state = caso.tipo === 'encender' ? true : caso.tipo === 'apagar' ? false : undefined;
return msg;

// Siempre se publica en el topic fijo del gateway:
//   simon/things/e45f01e7626f/apischuko
// deviceId y state los pone el propio nodo inject (msg.deviceId / msg.state).
// Token fijo (el mismo capturado del tráfico real de la app) - no depende de
// Environment Variables, así no hay que configurar nada aparte en Node-RED.
const GATEWAY_ID = 'e45f01e7626f';
const BASIC_TOKEN = 'YWRtaW46ODk5YTgwNzI3ZGExZGYwOGIxNTEzNmE4YTg5OTUwNjMzYjFjODQ0NmQyZjYwZWFlZmUyNTExMWRmZjVmNTg5MQ==';
const corrId = msg._msgid;

// Guardamos qué acción era (on/off) para poder etiquetarla cuando llegue la
// confirmación (esa llega como mensaje NUEVO por MQTT, sin msg.state).
flow.set('mqtt_pending_' + corrId, { deviceId: msg.deviceId, state: msg.state });

msg.topic = 'simon/things/' + GATEWAY_ID + '/apischuko';
msg.payload = JSON.stringify({
    path: '/api/v1/devices/' + msg.deviceId,
    method: 'PATCH',
    response_topic: 'simon/things/' + GATEWAY_ID + '/gtg/devices/' + msg.deviceId + '/' + corrId,
    headers: {
        'Content-Type': 'application/json',
        'Authorization': 'Basic ' + BASIC_TOKEN
    },
    data: JSON.stringify({ socket: { default: { state: msg.state } } })
});
return msg;

// AJUSTA a tu Grafana (misma URL/API key que en la pestaña HTTP):
const GRAFANA_URL = 'http://localhost:3000';
const GRAFANA_API_KEY = 'pon-aqui-tu-api-key-de-grafana';

// topic: simon/things/{gw}/gtg/devices/{deviceId}/{corrId}
// split('/') -> [0]simon [1]things [2]gw [3]gtg [4]devices [5]deviceId [6]corrId
const parts = msg.topic.split('/');
const deviceId = parts[5] || 'unknown';
const corrId = parts[6];
const data = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload;
const code = parseInt(data.code, 10) || 0;
const ok = code > 0 && code < 400;

// Recuperamos si el comando original era encender/apagar (lo guardó
// 'Preparar topic y payload' al publicar, usando el mismo corrId).
// (no borramos la entrada de flow context aquí - también la lee
// 'Preparar punto InfluxDB (éxito/fallo)' en paralelo)
const pending = flow.get('mqtt_pending_' + corrId);
const action = pending ? (pending.state ? 'on' : 'off') : 'unknown';
const combo = action + '_' + (ok ? 'success' : 'fail');

msg.headers = {
    'Content-Type': 'application/json',
    'Authorization': 'Bearer ' + GRAFANA_API_KEY
};
msg.url = GRAFANA_URL + '/api/annotations';
msg.payload = {
    time: Date.now(),
    tags: ['simonio', 'command', 'deviceId:' + deviceId, 'mqtt', action, ok ? 'success' : 'fail', combo],
    text: 'Comando MQTT PATCH (' + action + ') -> ' + code + (ok ? ' (éxito)' : ' (fallo)')
};
return msg;

// Sin base de datos externa: solo actualiza el contador en memoria de
// Node-RED (contexto global). Lo expone el endpoint HTTP GET /simonio/stats
// (pestaña HTTP, nodos 'Endpoint estadísticas') para que Grafana lo lea con
// el plugin Infinity.

// topic: simon/things/{gw}/gtg/devices/{deviceId}/{corrId}
const parts = msg.topic.split('/');
const deviceId = parts[5] || 'unknown';
const corrId = parts[6];
const data = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload;
const code = parseInt(data.code, 10) || 0;
const ok = code > 0 && code < 400;
const result = ok ? 'success' : 'fail';

const pending = flow.get('mqtt_pending_' + corrId);
const action = pending ? (pending.state ? 'on' : 'off') : 'unknown';

// Comparte contador con la pestaña HTTP (misma clave), para tener el total
// combinado HTTP+MQTT; si prefieres separarlos, añade '_mqtt' a la clave.
const key = 'simonio_count_' + deviceId + '_' + action + '_' + result;
const count = (global.get(key) || 0) + 1;
global.set(key, count);

return null;

// AJUSTA a tu Grafana (misma URL/API key que en la pestaña HTTP):
const GRAFANA_URL = 'http://localhost:3000';
const GRAFANA_API_KEY = 'pon-aqui-tu-api-key-de-grafana';

// topic: simon/telemetry/{gw}/{deviceId}/update
const deviceId = msg.topic.split('/')[3] || 'unknown';
const data = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload;
const state = data.socket && data.socket.default ? data.socket.default.state : null;
if (state === null) { return null; }

msg.headers = {
    'Content-Type': 'application/json',
    'Authorization': 'Bearer ' + GRAFANA_API_KEY
};
msg.url = GRAFANA_URL + '/api/annotations';
msg.payload = {
    time: Date.now(),
    tags: ['simonio', 'state', 'deviceId:' + deviceId, state ? 'on' : 'off'],
    text: 'Enchufe ' + deviceId + ' -> ' + (state ? 'ENCENDIDO' : 'APAGADO')
};
return msg;
